#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, source;
    cin >> n >> m >> source;
    vector<vector<pair<int, int>>> graph(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        graph[u].push_back({v, w});
        graph[v].push_back({u, w});
    }
    const long long INF = (1LL << 62);
    vector<long long> distance(n + 1, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    distance[source] = 0;
    pq.push({0, source});
    while (!pq.empty()) {
        auto [dist, vertex] = pq.top();
        pq.pop();
        if (dist != distance[vertex]) continue;
        for (auto [next, weight] : graph[vertex]) {
            if (distance[vertex] + weight < distance[next]) {
                distance[next] = distance[vertex] + weight;
                pq.push({distance[next], next});
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        if (distance[i] >= INF / 2) cout << -1 << ' ';
        else cout << distance[i] << ' ';
    }
    return 0;
}
